import math

def _tv(t, k):
    try:
        return t[k]
    except Exception:
        pass
    if k == 'north_m':
        return t.north_m
    if k == 'east_m':
        return t.east_m
    return t.radius_m

def _segd(px, py, qx, qy, cx, cy):
    dx = qx - px
    dy = qy - py
    l2 = dx * dx + dy * dy
    if l2 < 1e-9:
        return math.hypot(cx - px, cy - py)
    t = ((cx - px) * dx + (cy - py) * dy) / l2
    t = max(0.0, min(1.0, t))
    return math.hypot(cx - (px + t * dx), cy - (py + t * dy))

def decide(ctx):
    g = ctx.goal
    n = ctx.north_m
    e = ctx.east_m
    dn = g.target_north_m - n
    de = g.target_east_m - e
    dist = math.hypot(dn, de)
    vmax = g.max_speed_ms
    s = min(vmax, 0.5 * dist)
    if dist < 0.2:
        s = 0.0
    bearing = math.atan2(de, dn)
    thr = []
    for t in ctx.threats:
        thr.append((_tv(t, 'north_m'), _tv(t, 'east_m'), _tv(t, 'radius_m')))
    vn = s * math.cos(bearing)
    ve = s * math.sin(bearing)
    if thr and s > 0:
        L = min(max(dist, 5.0), 15.0)
        found = False
        offs = [0]
        for k in range(1, 13):
            offs.append(k * 15)
            offs.append(-k * 15)
        for margin in (3.0, 1.5, 0.5):
            for o in offs:
                a = bearing + math.radians(o)
                qn = n + L * math.cos(a)
                qe = e + L * math.sin(a)
                ok = True
                for (cn, ce, r) in thr:
                    if _segd(n, e, qn, qe, cn, ce) < r + margin:
                        ok = False
                        break
                if ok:
                    vn = s * math.cos(a)
                    ve = s * math.sin(a)
                    found = True
                    break
            if found:
                break
        if not found:
            vn = 0.0
            ve = 0.0
    alt = ctx.alt_m
    if dist < 1.0:
        vd = min(2.0, max(0.5, 0.5 * alt))
        if alt <= 1.0:
            vd = min(vd, 0.6)
    else:
        if alt < 3.0:
            vd = -1.0
        else:
            vd = 0.0
    nn = n + vn
    ee = e + ve
    if math.hypot(nn, ee) > g.fence_m - 2.0:
        vn = -n * 0.2
        ve = -e * 0.2
    return {'vn': vn, 've': ve, 'vd': vd}

