import math

def decide(ctx):
    g = ctx.goal
    dx = g.target_north_m - ctx.north_m
    dy = g.target_east_m - ctx.east_m
    d = math.hypot(dx, dy)
    if d < 1e-6:
        return {"vn": 0.0, "ve": 0.0}
    vmax = g.max_speed_ms * 0.98
    s = min(vmax, 0.5 * d)
    base = math.atan2(dy, dx)
    margin = 2.0
    threats = list(ctx.threats or [])
    sgn = 1.0
    if threats:
        best = None
        for t in threats:
            td = math.hypot(t.north_m - ctx.north_m, t.east_m - ctx.east_m)
            if best is None or td < best[0]:
                best = (td, t)
        t = best[1]
        tx = t.north_m - ctx.north_m
        ty = t.east_m - ctx.east_m
        cr = dx * ty - dy * tx
        sgn = -1.0 if cr > 0 else 1.0
    angs = [0]
    for a in range(15, 181, 15):
        angs.append(a)
        angs.append(-a)
    cands = []
    for a in angs:
        if a == 0:
            cands.append(0.0)
        else:
            cands.append(math.radians(a) * sgn)
    def clearance(th):
        ux = math.cos(th)
        uy = math.sin(th)
        mn = 1e9
        for k in range(1, 5):
            L = min(s * k, d)
            px = ctx.north_m + ux * L
            py = ctx.east_m + uy * L
            c = g.fence_m - 2.0 - math.hypot(px, py)
            if c < mn:
                mn = c
            for t in threats:
                c = math.hypot(px - t.north_m, py - t.east_m) - (t.radius_m + margin)
                if c < mn:
                    mn = c
        return mn
    chosen = None
    bestc = -1e9
    bestth = base
    for off in cands:
        th = base + off
        c = clearance(th)
        if c >= 0:
            chosen = th
            break
        if c > bestc:
            bestc = c
            bestth = th
    if chosen is None:
        chosen = bestth
    return {"vn": s * math.cos(chosen), "ve": s * math.sin(chosen)}

