import math

def _segd(px, py, qx, qy, cx, cy):
    dx = qx - px
    dy = qy - py
    l2 = dx * dx + dy * dy
    if l2 < 1e-9:
        return math.hypot(cx - px, cy - py)
    t = ((cx - px) * dx + (cy - py) * dy) / l2
    t = max(0.0, min(1.0, t))
    return math.hypot(cx - (px + t * dx), cy - (py + t * dy))

def decide(ctx):
    g = ctx.goal
    n = ctx.north_m
    e = ctx.east_m
    a = ctx.alt_m
    dn = g.target_north_m - n
    de = g.target_east_m - e
    d = math.hypot(dn, de)
    vmax = min(g.max_speed_ms, 5.0) * 0.9
    sp = min(vmax, 0.5 * d)
    if d < 0.05:
        sp = 0.0
    base = math.atan2(de, dn)
    L = min(max(d, 1.0), 12.0)
    margin = 2.0
    best = None
    if sp > 0:
        cands = [0]
        for k in range(1, 37):
            cands.append(k)
            cands.append(-k)
        for k in cands:
            ang = base + math.radians(5.0 * k)
            un = math.cos(ang)
            ue = math.sin(ang)
            ok = True
            for t in ctx.threats:
                r = t.radius_m + margin
                dist0 = math.hypot(n - t.north_m, e - t.east_m)
                if dist0 <= r:
                    if un * (n - t.north_m) + ue * (e - t.east_m) < 0:
                        ok = False
                        break
                else:
                    if _segd(n, e, n + L * un, e + L * ue, t.north_m, t.east_m) <= r:
                        ok = False
                        break
            if ok:
                best = (un, ue)
                break
    if best is None:
        vn = 0.0
        ve = 0.0
    else:
        vn = sp * best[0]
        ve = sp * best[1]
    if math.hypot(n + vn, e + ve) > g.fence_m - 2.0:
        vn = 0.0
        ve = 0.0
    err = g.target_alt_m - a
    vm = min(g.max_vertical_ms, 2.0) * 0.9
    vd = -max(-vm, min(vm, 0.6 * err))
    return {"vn": vn, "ve": ve, "vd": vd}
